from lib import *
S = SS('w80')
steps = [
    step("服务器按 Accept-Encoding 选压缩方式。python.org 的 CSS(文本,349113 字节):identity → 不压缩 349113 字节;gzip → 125147 字节(−64%);br、zstd、deflate → 服务器都不支持,依旧发 349113 字节的原文;\"gzip, br, zstd\" → 选了 gzip。响应头 Vary: Accept-Encoding——告诉缓存这份内容随 Accept-Encoding 而变。example.com 首页(577 字节的 HTML):identity 577 字节;gzip 400 字节;br 334 字节;zstd、deflate 不支持,发 577 字节;\"gzip, br, zstd\" → 选 br(334 字节)。每一种压缩版本解压后与原文逐字节一致。还有一个怪现象:python.org 首页 / 即使请求里写了 Accept-Encoding: identity,响应仍然是 gzip 的 11161 字节——这个服务器没有听从 identity,它的 Vary 只写了 Cookie,没写 Accept-Encoding。", t=tl(S(1)), mark=lidx(S(1), 'Accept-Encoding: gzip            →', 'Accept-Encoding: br              →', 'python.org 首页 /'), done=lidx(S(1), 'Accept-Encoding: identity', 'Accept-Encoding: zstd', 'Accept-Encoding: deflate'), b=bars([['CSS 原文', 349113, '349113 字节'], ['CSS gzip', 125147, '125147 字节'], ['首页 identity', 577, '577 字节'], ['首页 gzip', 400, '400 字节'], ['首页 br', 334, '334 字节']], 349113, mark=[1, 4], done=[0, 2, 3]), kv=KV([['python.org CSS', '只支持 gzip(−64%),不支持 br / zstd / deflate'], ['example.com 首页', 'br 334 < gzip 400 < 原文 577'], ['python.org 首页', '无视 identity,仍发 gzip']], ['python.org CSS'])),
    step("q 值与特殊写法,对 example.com 首页。\"gzip;q=0.5, br;q=1\" → br(334 字节);\"br;q=0.1, gzip;q=0.9\" → 仍然是 br,本该选 gzip 的(这个服务器看起来不按 q 值排序,只是偏好 br);\"br;q=0, gzip\" → 仍然是 br,而 q=0 明明表示“不接受 br”;\"gzip;q=0, br;q=0\" → 还是 br。“*”、\"*;q=0\"、\"identity;q=0\"、\"compress\" → 不压缩的 577 字节;写成大写 \"GZIP\" → gzip,说明编码名字不区分大小写。结论:对这一台服务器,q=0 的“拒绝”并没有被尊重;写客户端时不要指望靠 q 值禁用某种编码。", t=tl(S(2)), mark=lidx(S(2), 'br;q=0, gzip', 'gzip;q=0, br;q=0', 'br;q=0.1'), done=lidx(S(2), 'gzip;q=0.5, br;q=1', 'Accept-Encoding: *  ', 'GZIP', 'compress'), kv=KV([['q=0 的编码', '仍然被选中(br)'], ['q 值高低', '没有按 q 值排序(偏好 br)'], ['大小写', 'GZIP 也认']], ['q=0 的编码'])),
    step("压缩算法与级别(把 python.org 的 349113 字节 CSS 在本机压一遍):gzip -1 → 142494 字节(40.8%),5.6 ms;gzip -6(常用默认)→ 125147(35.8%),10.7 ms,与真实服务器的 gzip 版本一模一样大;gzip -9 → 124789(35.7%),12.3 ms——比 -6 只多省 0.3%,慢了 15%。brotli q1 → 131508(37.7%),1.2 ms;q5 → 109810(31.5%),5.4 ms;q11 → 98381(28.2%),431.6 ms,约为 q5 的 80 倍,只适合离线预压缩。zstd -1 → 129255(37.0%),0.7 ms;-3(默认)→ 119137(34.1%),1.0 ms;-19 → 106191(30.4%),57.4 ms。解压都很快(0.3~1.0 ms,gzip -1 的 0.8 ms 偏高是计时抖动),所以服务器在压缩端的 CPU 代价才是权衡点:brotli q5 和 zstd -3 比 gzip -6 既更小又不更慢。", t=tl(S(3)), mark=lidx(S(3), 'gzip -6', 'brotli q11', 'zstd -3'), done=lidx(S(3), 'gzip -1', 'gzip -9', 'brotli q1', 'brotli q5', 'zstd -1', 'zstd -19'), b=bars([['gzip -6', 35.8, '35.8%'], ['gzip -9', 35.7, '35.7%'], ['brotli q5', 31.5, '31.5%'], ['brotli q11', 28.2, '28.2%'], ['zstd -3', 34.1, '34.1%'], ['zstd -19', 30.4, '30.4%']], 40, mark=[2, 4], done=[0, 1, 3, 5]), kv=KV([['gzip -6', '35.8%,10.7 ms'], ['brotli q5', '31.5%,5.4 ms'], ['brotli q11', '28.2%,431.6 ms'], ['zstd -3', '34.1%,1.0 ms']], ['brotli q5'])),
    step("已经压缩过的数据再压一次没有收益。同样的两种算法:CSS 文本 349113 字节 → gzip 35.8%、brotli q5 31.5%;PNG 图片(已经是压缩格式)15770 字节 → gzip 98.3%、brotli 99.1%;随机字节 100000 字节 → gzip 100.1%(反而变大)、brotli 100.0%;已经 gzip 过的 CSS 再 gzip 一次 → 99.8%,brotli → 100.0%。所以压缩只该用在文本类内容(HTML、CSS、JS、JSON),对图片、视频、已压缩包不要再压——白花 CPU,有时还会变大。", t=tl(S(4)), mark=lidx(S(4), 'PNG 图片', '随机字节', '已经 gzip 过的 CSS'), done=lidx(S(4), 'CSS 文本'), b=bars([['CSS 文本 gzip', 35.8, '35.8%'], ['PNG gzip', 98.3, '98.3%'], ['随机字节 gzip', 100.1, '100.1%'], ['已 gzip 的 CSS 再 gzip', 99.8, '99.8%']], 100, mark=[1, 2, 3], done=[0]), kv=KV([['文本', '压到 31%~36%'], ['PNG / 随机 / 再压缩', '98%~100%,几乎没有收益']], ['PNG / 随机 / 再压缩'])),
    step("压缩划不划算取决于链路。本机服务器把同一个 CSS 以原样 / gzip -6 / brotli q5 发出,netlab 每方向延迟 20 ms,下载 + 解压的总时间。1 Mbit/s:原样 2889 ms,gzip 1094 ms,brotli 970 ms——快 2.6~3.0 倍。10 Mbit/s:原样 366 ms,gzip 186 ms,brotli 174 ms。不限速(1000 Mbit/s 级别):原样 122 ms,gzip 83 ms,brotli 83 ms——没有带宽瓶颈时仍然快了 32%,因为字节少了,往返次数也少了(慢启动阶段每个 RTT 只能发有限的包)。解压只花 0.6~1.3 ms,在任何带宽下都远小于省下的传输时间。", t=tl(S(5)), mark=lidx(S(5), '1 Mbit/s', '10 Mbit/s', '1000 Mbit/s'), done=lidx(S(5), '带宽'), b=bars([['1 Mbit/s 原样', 2889, '2889 ms'], ['1 Mbit/s gzip', 1094, '1094 ms'], ['1 Mbit/s brotli', 970, '970 ms'], ['无限速 原样', 122, '122 ms'], ['无限速 gzip', 83, '83 ms']], 2889, mark=[1, 2, 4], done=[0, 3]), kv=KV([['1 Mbit/s', '2889 → 1094 / 970 ms'], ['10 Mbit/s', '366 → 186 / 174 ms'], ['不限速', '122 → 83 ms'], ['解压', '0.6~1.3 ms,可忽略']], ['1 Mbit/s'])),
]
